import json,urllib.request,urllib.parse,re,subprocess,sys,os,xml.etree.ElementTree as ET
D='/Users/kristinarash/.claude/jobs/244669f2/tmp/ssr-pdfs'
UA='Mozilla/5.0 (ssr-fetch mailto:eric.rash11@gmail.com)'
def get(u,raw=False):
    r=urllib.request.Request(u,headers={'User-Agent':UA})
    d=urllib.request.urlopen(r,timeout=40).read()
    return d if raw else json.loads(d)
dois=[l.split()[2] for l in open('/tmp/ssr_dois.txt')]
titles=[l.strip() for l in open('/tmp/ssr_list.txt')]
def norm(s): return re.sub(r'[^a-z0-9]','',s.lower())
def s3(pmc):
    x=urllib.request.urlopen(urllib.request.Request('https://pmc-oa-opendata.s3.amazonaws.com/?list-type=2&prefix=%s.'%pmc,headers={'User-Agent':UA}),timeout=30).read().decode()
    keys=re.findall(r'<Key>([^<]+\.pdf)</Key>',x,re.I)
    keys=[k for k in keys if '/' in k and not re.search(r'ESM|Data_Sheet|supp',k,re.I)]
    keys.sort(key=lambda k:int(re.search(r'\.(\d+)/',k).group(1)) if re.search(r'\.(\d+)/',k) else 0,reverse=True)
    return ['https://pmc-oa-opendata.s3.amazonaws.com/'+k for k in keys[:1]]
def cands(doi):
    c=[]
    try:
        u=get('https://api.unpaywall.org/v2/%s?email=eric.rash11@gmail.com'%doi)
        for l in u.get('oa_locations',[]):
            for k in ('url_for_pdf',):
                if l.get(k): c.append(l[k])
            m=re.search(r'PMC?(\d+)',(l.get('url') or ''))
            if m and 'ncbi' in l['url']: c=s3('PMC'+m.group(1))+c
    except Exception as e: print('unp',e)
    try:
        j=get('https://www.ebi.ac.uk/europepmc/webservices/rest/search?format=json&query=DOI:%s'%urllib.parse.quote(doi))
        for r in j['resultList']['result']:
            if r.get('pmcid') and r.get('isOpenAccess')=='Y': c=s3(r['pmcid'])+c
    except Exception as e: print('epmc',e)
    return list(dict.fromkeys(c))
def verify(path,title):
    if open(path,'rb').read(5)!=b'%PDF-': return False,'no %PDF header'
    t=subprocess.run(['pdftotext','-l','3',path,'-'],capture_output=True,text=True).stdout
    n=norm(t); w=norm(re.sub(r'\.pdf$','',title))
    # compare first 40 chars of title
    key=w[:40]
    return (key in n), ('title found' if key in n else 'title not in first 3 pages')
for i in map(int,sys.argv[1:]):
    doi=dois[i];t=titles[i]
    out=os.path.join(D,'%02d.pdf'%i)
    if os.path.exists(out): print(i,'exists');continue
    ok=False
    for u in cands(doi):
        try:
            d=get(u,True)
        except Exception as e:
            print(i,'fail',u[:80],str(e)[:50]);continue
        p=out+'.try'
        open(p,'wb').write(d)
        v,msg=verify(p,t)
        print(i,doi,u[:90],len(d),msg)
        if v: os.rename(p,out);ok=True;open(out+'.src','w').write(u);break
    if not ok: print(i,'NOT OBTAINED')
